{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"export const RELIABILITY_OUTCOMES = Object.freeze([
  'pass',
  'fail',
  'rejected',
  'missing',
  'timeout',
  'crash',
  'skip',
]);

function outcomeOf(trial) {
  if (typeof trial === 'string') return trial;
  return trial?.outcome ?? trial?.status ?? 'missing';
}

function isTerminal(outcome) {
  return outcome === 'pass' || outcome === 'fail' || outcome === 'rejected';
}

function isSuccessful(trial, kind) {
  const outcome = outcomeOf(trial);
  return kind === 'negative' ? outcome === 'rejected' : outcome === 'pass';
}

function ratio(numerator, denominator) {
  return denominator === 0 ? null : Number((numerator / denominator).toFixed(6));
}

/**
 * Aggregate repeated-trial results without hiding incomplete cases. A case is
 * complete only when every registered trial has a terminal result. Missing,
 * timeout, crash, and skip cases remain in the report but are not in pass@k
 * or pass^k denominators.
 */
export function aggregateReliability(fixture) {
  const k = Number(fixture?.k);
  const minCases = Number(fixture?.minCases);
  if (!Number.isInteger(k) || k < 1) throw new TypeError('reliability fixture k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 1) throw new TypeError('reliability fixture minCases must be a positive integer');

  const cases = Array.isArray(fixture?.cases) ? fixture.cases : [];
  const complete = [];
  const incomplete = [];
  const perTrial = [];
  let passAtK = 0;
  let passAllK = 0;
  let flake = 0;
  let firstFailure = 0;
  let skipped = 0;
  let timedOut = 0;
  let crashed = 0;
  let missing = 0;

  for (const item of cases) {
    const kind = item.kind ?? item.anchor ?? 'ordinary';
    const trials = Array.isArray(item.trials) ? item.trials : [];
    const outcomes = trials.map(outcomeOf);
    const incompleteReasons = outcomes.filter((outcome) => !isTerminal(outcome));
    const completeCase = trials.length === k && incompleteReasons.length === 0;
    const successful = trials.filter((trial) => isSuccessful(trial, kind)).length;
    const first = outcomes[0];
    const firstFailed = first === 'fail' || first === 'timeout' || first === 'crash' || first === 'skip' || first === 'missing';
    const laterSuccess = outcomes.slice(1).some((outcome, index) => isSuccessful(trials[index + 1], kind));
    const isFlake = completeCase && firstFailed && laterSuccess;
    const entry = {
      id: item.id,
      kind,
      safety: Boolean(item.safety),
      complete: completeCase,
      trials: outcomes,
      passCount: successful,
      passAtK: successful > 0,
      passAllK: successful === k,
      flake: isFlake,
      firstFailure: firstFailed,
      incomplete: incompleteReasons.length > 0 || trials.length !== k,
      incompleteReasons,
    };
    perTrial.push(entry);
    if (!completeCase) {
      incomplete.push(entry);
      missing += outcomes.filter((outcome) => outcome === 'missing').length;
      timedOut += outcomes.filter((outcome) => outcome === 'timeout').length;
      crashed += outcomes.filter((outcome) => outcome === 'crash').length;
      skipped += outcomes.filter((outcome) => outcome === 'skip').length;
      continue;
    }
    complete.push(entry);
    if (entry.passAtK) passAtK += 1;
    if (entry.passAllK) passAllK += 1;
    if (isFlake) flake += 1;
    if (firstFailed) firstFailure += 1;
  }

  const denominator = complete.length;
  const positive = perTrial.filter((item) => item.kind === 'positive');
  const negative = perTrial.filter((item) => item.kind === 'negative');
  const anchorViolations = perTrial.filter((item) => {
    if (item.kind === 'positive') return !item.complete || !item.passAllK;
    if (item.kind === 'negative') return !item.complete || !item.passAllK;
    return false;
  });
  const safety = perTrial.filter((item) => item.safety);
  const safetyViolations = safety.filter((item) => item.trials.includes('skip') || item.flake);
  const reasons = [];
  if (denominator < minCases) reasons.push(`complete cases ${denominator} < design gate ${minCases}`);
  if (anchorViolations.length) reasons.push(`${anchorViolations.length} anchor violation(s)`);
  if (safetyViolations.length) reasons.push(`${safetyViolations.length} safety case(s) with skip or flake`);

  let gate = 'pass';
  if (reasons.length) gate = denominator < minCases && !anchorViolations.length && !safetyViolations.length ? 'insufficient-sample' : 'fail';

  return {
    k,
    minCases,
    rawCaseCount: cases.length,
    completeCaseCount: denominator,
    incompleteCaseCount: incomplete.length,
    passAtK: ratio(passAtK, denominator),
    passAllK: ratio(passAllK, denominator),
    flake: ratio(flake, denominator),
    firstFailure: ratio(firstFailure, denominator),
    missing,
    timeout: timedOut,
    crash: crashed,
    skip: skipped,
    passAtKCount: passAtK,
    passAllKCount: passAllK,
    flakeCount: flake,
    positive: { count: positive.length, violations: anchorViolations.filter((item) => item.kind === 'positive').map((item) => item.id) },
    negative: { count: negative.length, violations: anchorViolations.filter((item) => item.kind === 'negative').map((item) => item.id) },
    safety: { count: safety.length, skipOrFlake: safetyViolations.map((item) => item.id) },
    gate,
    reasons,
    cases: perTrial,
    incomplete,
  };
}

export const evaluateReliability = aggregateReliability;
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"export type ReliabilityOutcome = 'pass' | 'fail' | 'rejected' | 'missing' | 'timeout' | 'crash' | 'skip';

export interface ReliabilityTrial {
  outcome?: ReliabilityOutcome;
  status?: ReliabilityOutcome;
}

export interface ReliabilityCase {
  id: string;
  kind?: 'ordinary' | 'positive' | 'negative';
  anchor?: 'ordinary' | 'positive' | 'negative';
  safety?: boolean;
  trials: Array<ReliabilityTrial | ReliabilityOutcome>;
}

export interface ReliabilityFixture {
  k: number;
  minCases: number;
  cases: ReliabilityCase[];
}

export interface ReliabilityCaseResult extends ReliabilityCase {
  complete: boolean;
  passCount: number;
  passAtK: boolean;
  passAllK: boolean;
  flake: boolean;
  firstFailure: boolean;
  incomplete: boolean;
  incompleteReasons: ReliabilityOutcome[];
}

export interface ReliabilityReport {
  k: number;
  minCases: number;
  rawCaseCount: number;
  completeCaseCount: number;
  incompleteCaseCount: number;
  passAtK: number | null;
  passAllK: number | null;
  flake: number | null;
  firstFailure: number | null;
  missing: number;
  timeout: number;
  crash: number;
  skip: number;
  passAtKCount: number;
  passAllKCount: number;
  flakeCount: number;
  positive: { count: number; violations: string[] };
  negative: { count: number; violations: string[] };
  safety: { count: number; skipOrFlake: string[] };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: ReliabilityCaseResult[];
  incomplete: ReliabilityCaseResult[];
}

export declare function aggregateReliability(fixture: ReliabilityFixture): ReliabilityReport;
export declare const evaluateReliability: typeof aggregateReliability;
