    k,
    minCases,
    rawCaseCount: cases.length,
    completeCaseCount: denominator,
    incompleteCaseCount: incomplete.length,
    passAtK: ratio(passAtK, denominator),
    passAllK: ratio(passAllK, denominator),
    flake: ratio(flake, denominator),
    firstFailure: ratio(firstFailure, denominator),
    missing,
    timeout: timedOut,
    crash: crashed,
    skip: skipped,
    passAtKCount: passAtK,
    passAllKCount: passAllK,
    flakeCount: flake,
    positive: { count: positive.length, violations: anchorViolations.filter((item) => item.kind === 'positive').map((item) => item.id) },
    negative: { count: negative.length, violations: anchorViolations.filter((item) => item.kind === 'negative').map((item) => item.id) },
    safety: { count: safety.length, skipOrFlake: safetyViolations.map((item) => item.id) },
    gate,
    reasons,
    cases: perTrial,
    incomplete,
  };
